'use strict';
const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto');
const E=require('./src/engine.js'),H=require('./src/horizon-models.js');
const stable=v=>v===null||typeof v!=='object'?JSON.stringify(v):Array.isArray(v)?'['+v.map(stable).join(',')+']':'{'+Object.keys(v).sort().map(k=>JSON.stringify(k)+':'+stable(v[k])).join(',')+'}';
const digest=v=>crypto.createHash('sha256').update(stable(v)).digest('hex');
const byteDigest=b=>crypto.createHash('sha256').update(b).digest('hex');
const stamp='2026-10-11T20:00:00.000Z';
function build(){
 const registry=JSON.parse(fs.readFileSync(path.join(__dirname,'horizon-equations.json'),'utf8'));
 const previous=JSON.parse(fs.readFileSync(path.join(__dirname,'equation-audit.json'),'utf8'));
 const result=H.all(registry,previous);if(!result.passed)throw Error('Horizon adapter checks failed.');
 if(result.coverage.pdfNumberedEquations!==23)throw Error('Expected all 23 numbered PDF equations.');
 const originals=['Black_Hole_Master_Equations.pdf','ETM.jpg','eventHorizon.jpg','aggie aperture.png','Screenshot 2026-10-11 053124.png','User_Simulation_Writeup.txt'];
 result.sources=originals.map(name=>{const file='reference/blackhole-specification/'+name,b=fs.readFileSync(path.join(__dirname,file));return {path:file,name,bytes:b.length,sha256:byteDigest(b),role:name==='User_Simulation_Writeup.txt'?'USER HYPOTHESIS':'SUPPLIED EQUATION SOURCE'};});
 result.preparedAt=stamp;result.equationRegistry=registry;
 result.simulationSpecification={schema:'RUSSL-horizon-simulation-specification/1',version:'0.4.0',userWriteup:fs.readFileSync(path.join(__dirname,'reference/blackhole-specification/User_Simulation_Writeup.txt'),'utf8'),specificationText:fs.readFileSync(path.join(__dirname,'docs/Horizon_Simulation_Specification.txt'),'utf8'),defaults:result.scenario.parameters,assumptions:['shared exterior parameters','near-extremal spin chosen, not inferred','toy aperture function','cover load threshold','hypothetical passage bit'],observationProtocols:{exteriorOnly:result.scenario.observations.protocol,optionalPassage:result.scenario.optionalPassageProbe.protocol},unresolved:result.scenario.electromagneticClaim,physicalStatus:'Hypothetical specification with separately audited standard reference values.'};
 function snap(field,vector,description,ops,prep){return {model:{schema:'RUSSL-finite-field-model/1',field:E.fields[field],labelEncoding:'integer = sum(c_i * p^i), polynomial coefficients low first',amplitudes:'complex floating point',fourierSign:'+2pi i',normalization:'1/sqrt(q)',character:'exp(2pi i Tr(x)/p)',tolerance:E.tolerance,backend:'local browser JavaScript',physicalScope:'finite-dimensional complex-amplitude simulation'},state:vector,description,operations:ops,normSquared:E.norm(vector)**2,...(prep?{preparation:prep}:{})};}
 const s=result.finalState,final=snap(s.field,s.vector,s.description,3,s.preparation);
 const states=[final,snap('gf9',result.toyProfiles.aperture.preparedState,'Hypothetical aperture profile → GFM',1,result.toyProfiles.aperture.preparation),snap('gf9',result.previousReapplication.finalState.vector,'Prior pendulum GFM example',3,result.previousReapplication.finalState.preparation)];
 const records=states.map((snapshot,i)=>{const data={schema:'RUSSL-research-record/1',kind:'gf-state',label:snapshot.description,capturedAt:stamp,payload:{snapshot,verification:E.audit(E.field(snapshot.model.field.id),snapshot.state),scope:i===1?'hypothetical toy signal':'declared finite signal demonstration'}};const sha256=digest(data);return {id:'rec-horizon-'+(i+1)+'-'+sha256.slice(0,8),sha256,data};});
 const data={schema:'RUSSL-virtual-session/1',version:'0.4.0',kind:'session',exportedAt:stamp,snapshot:final,horizonSimulation:{parameters:result.scenario.parameters,probe:"exterior"},records,commandProvenance:['horizon.reapply'],returns:[{id:'ret-horizon-reapplication',command:'horizon.reapply',ok:true,summary:'Audited equations and hypothetical specification integrated; exterior observations remain unidentifiable.',profile:'Horizon / declared standard and hypothetical domains',elapsedMs:0,details:result}]};
 return {result,packet:{sha256:digest(data),data}};
}
if(require.main===module){const {result,packet}=build();fs.writeFileSync(path.join(__dirname,'horizon-reapplication.json'),JSON.stringify(result,null,2)+'\n');fs.writeFileSync(path.join(__dirname,'examples/Horizon-Simulation-session.json'),JSON.stringify(packet,null,2)+'\n');const config=JSON.parse(fs.readFileSync(path.join(__dirname,'source-register.json'),'utf8'));config.version='0.4.0';config.sources=config.sources.filter(s=>!s.path.startsWith('reference/blackhole-specification/'));config.sources.push(...result.sources.map(s=>({...s,title:s.name,scope:s.role==='USER HYPOTHESIS'?'User-proposed formation, cover and passage rules, preserved as inert reference data.':'Equations retained with separate domain and applicability audit.'})));fs.writeFileSync(path.join(__dirname,'source-register.json'),JSON.stringify(config,null,2)+'\n');console.log('Built audited horizon report, specification and reloadable 0.4 session.');}
module.exports={build,stable,digest};
